use verus::prelude::*;

verus! {

    /// reverse takes a reference to a Vec<i32> `a` and returns
    /// a new Vec<i32> whose elements are in the reverse order of `a`.
    ///
    /// ensures:
    ///   - The result has the same length as the input.
    ///   - For every index i in [0, n), result[i] == a[n - 1 - i].
    pub fn reverse(a: &Vec<i32>) -> Vec<i32>
        ensures
            |res: &Vec<i32>|
                res.len() == a.len()
                &&
                forall(|i: usize| i < a.len() ==> res[i] == a[a.len() - 1 - i])
    {
        let n: usize = a.len();

        // Build up the result incrementally.
        let mut res: Vec<i32> = Vec::new();
        let mut i: usize = 0;

        // Loop invariant tracks that we've inserted exactly i elements,
        // and they satisfy the reverse-property for indices [0, i).
        while i < n
            invariant i <= n
            invariant res.len() == i
            invariant forall(|j: usize| j < i ==> res[j] == a[n - 1 - j])
            decreases n - i
        {
            // Take the next element from the end of `a` and push it onto `res`.
            res.push(a[n - 1 - i]);
            i = i + 1;
        }

        // At this point i == n, so res.len() == n, and the invariant
        // gives us the full reverse-property for all indices.
        res
    }

    // A simple proof harness (optional) to test the verifier.
    proof fn test_reverse_empty() {
        let a: Vec<i32> = Vec::new();
        let r = reverse(&a);
        assert(r.len() == 0);
    }

    proof fn test_reverse_nonempty() {
        let a = vec![1, 2, 3, 4];
        let r = reverse(&a);
        assert(r.len() == 4);
        assert(r[0] == 4);
        assert(r[1] == 3);
        assert(r[2] == 2);
        assert(r[3] == 1);
    }
}